// ---- geometry.js ----

// Gridfinity parts as triangle meshes, and binary STL. Every shell is closed and wound outward, so a part slices as
// it's drawn; a part made of several shells (a bin's feet, its body, its dividers) overlaps them slightly rather than
// letting faces touch, which slicers join cleanly.
//
// Sizes follow the Gridfinity system (Zack Freedman's, MIT): a 42 mm cell, bins 0.5 mm smaller than their cells,
// 7 mm height units, and the stepped profile that seats a bin's feet in the baseplate's pockets.

export const CELL = 42;
export const HEIGHT_UNIT = 7;
/** A bin is this much narrower than the cells it covers, so it drops into them. */
const BIN_CLEARANCE = 0.5;

// A bin's foot, from the bottom: a 0.8 mm chamfer, 1.8 mm straight, a 2.15 mm chamfer, as [height, inset, radius]
// from the full 41.5 mm size and 3.75 mm corner.
const FOOT = [
  [0, 2.95, 0.8],
  [0.8, 2.15, 1.6],
  [2.6, 2.15, 1.6],
  [4.75, 0, 3.75],
];
const FOOT_TOP = 4.75;
const BIN_RADIUS = 3.75;
const WALL = 1.2;
const FLOOR_TOP = 6;
const DIVIDER = 1.2;

// A baseplate pocket, from the bottom: 0.7 mm chamfer, 1.8 mm straight, 2.15 mm chamfer. Its opening is 41.9 mm rather
// than the cell's full 42, so neighbouring pockets keep a ridge between them.
const POCKET_OPENING = 41.9;
const POCKET = [
  [0, 2.85, 1.1],
  [0.7, 2.15, 1.8],
  [2.5, 2.15, 1.8],
  [4.65, 0, 3.95],
];
export const BASEPLATE_HEIGHT = 4.65;

// Points on each rounded corner; more is smoother and heavier.
const ARC = 6;

/** A rounded rectangle centred on (cx, cy), counter-clockwise: four arcs of ARC + 1 points, starting at the
 *  bottom-right corner's lowest point. */
function roundedRect(cx, cy, w, h, r) {
  const hw = w / 2;
  const hh = h / 2;
  const corners = [
    [cx + hw - r, cy - hh + r, -Math.PI / 2],
    [cx + hw - r, cy + hh - r, 0],
    [cx - hw + r, cy + hh - r, Math.PI / 2],
    [cx - hw + r, cy - hh + r, Math.PI],
  ];
  const points = [];
  for (const [ox, oy, start] of corners)
    for (let i = 0; i <= ARC; i++) {
      const a = start + (i / ARC) * (Math.PI / 2);
      points.push([ox + r * Math.cos(a), oy + r * Math.sin(a)]);
    }
  return points;
}

const at = (points, z) => points.map(([x, y]) => [x, y, z]);

class Mesh {
  constructor() {
    this.triangles = [];
  }
  tri(a, b, c) {
    this.triangles.push([a, b, c]);
  }
  quad(a, b, c, d) {
    this.tri(a, b, c);
    this.tri(a, c, d);
  }
  /** A convex polygon (counter-clockwise from above), facing up or down. */
  cap(loop, up) {
    for (let i = 1; i < loop.length - 1; i++)
      if (up) this.tri(loop[0], loop[i], loop[i + 1]);
      else this.tri(loop[0], loop[i + 1], loop[i]);
  }
  /** The band between two loops of as many points, the lower first; facing out, or in for a hole's walls. */
  wall(lower, upper, out = true) {
    const n = lower.length;
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      if (out) this.quad(lower[i], lower[j], upper[j], upper[i]);
      else this.quad(lower[j], lower[i], upper[i], upper[j]);
    }
  }
  /** The flat band between an outer and an inner loop of as many points, facing up or down. */
  band(outer, inner, up) {
    const n = outer.length;
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      if (up) this.quad(outer[i], outer[j], inner[j], inner[i]);
      else this.quad(outer[j], outer[i], inner[i], inner[j]);
    }
  }
  /** A closed box. */
  box(x0, y0, z0, x1, y1, z1) {
    const bottom = [
      [x0, y0, z0],
      [x1, y0, z0],
      [x1, y1, z0],
      [x0, y1, z0],
    ];
    const top = bottom.map(([x, y]) => [x, y, z1]);
    this.cap(bottom, false);
    this.cap(top, true);
    this.wall(bottom, top);
  }
}

/** A loft of rounded rectangles, closed at both ends: a bin's foot. */
function solidLoft(mesh, cx, cy, w, h, profile) {
  const loops = profile.map(([z, inset, r]) => at(roundedRect(cx, cy, w - 2 * inset, h - 2 * inset, r), z));
  mesh.cap(loops[0], false);
  for (let i = 0; i < loops.length - 1; i++) mesh.wall(loops[i], loops[i + 1]);
  mesh.cap(loops[loops.length - 1], true);
}

/**
 * The flat region between a rectangle and a rounded rectangle inside it, as the top or bottom of a baseplate cell:
 * the rectangle's corners each fan to their arc, and its sides meet the rounded rectangle's straight sides square on.
 * Returns the rectangle's boundary as each side's points in counter-clockwise order (bottom, right, top, left), for
 * the walls of a tile's outside.
 */
function rectAroundRounded(mesh, rect, inner, z, up) {
  const [x0, y0, x1, y1] = rect;
  const arcs = [0, 1, 2, 3].map((k) => inner.slice(k * (ARC + 1), (k + 1) * (ARC + 1)).map(([x, y]) => [x, y, z]));
  const corners = [
    [x1, y0, z],
    [x1, y1, z],
    [x0, y1, z],
    [x0, y0, z],
  ];
  // Where each arc's ends meet the rectangle: square on, on the side each end lies along.
  const project = (point, side) =>
    side === "bottom"
      ? [point[0], y0, z]
      : side === "right"
        ? [x1, point[1], z]
        : side === "top"
          ? [point[0], y1, z]
          : [x0, point[1], z];
  const before = ["bottom", "right", "top", "left"];
  const after = ["right", "top", "left", "bottom"];
  const starts = arcs.map((arc, k) => project(arc[0], before[k]));
  const ends = arcs.map((arc, k) => project(arc[ARC], after[k]));
  const t = (a, b, c) => (up ? mesh.tri(a, b, c) : mesh.tri(a, c, b));
  for (let k = 0; k < 4; k++) {
    const c = corners[k];
    const arc = arcs[k];
    t(c, ends[k], arc[ARC]);
    for (let i = ARC - 1; i >= 0; i--) t(c, arc[i + 1], arc[i]);
    t(c, arc[0], starts[k]);
    // The straight stretch to the next corner.
    const next = (k + 1) % 4;
    t(ends[k], starts[next], arcs[next][0]);
    t(ends[k], arcs[next][0], arc[ARC]);
  }
  // Each side of the rectangle, from corner to corner.
  return [0, 1, 2, 3].map((k) => {
    const prev = (k + 3) % 4;
    return [corners[prev], ends[prev], starts[k], corners[k]];
  });
}

/**
 * A baseplate tile of `cols` × `rows` pockets, `pitchX` × `pitchY` mm apart (42 for Gridfinity, more when cells are
 * stretched to fill a drawer), with a flat border of `pad` mm on each side, [left, right, bottom, top], filling the
 * drawer's leftover space along its walls. Open at the bottom, as a light baseplate, so it prints fast and lies flat.
 * Its corner is at the origin.
 */
export function baseplateTile({ cols, rows, pitchX = CELL, pitchY = CELL, pad = [0, 0, 0, 0] }) {
  const mesh = new Mesh();
  const [left, right, bottom, topPad] = pad;
  // Grid lines, then the outermost moved out by the border.
  const gx = Array.from({ length: cols + 1 }, (_, i) => left + i * pitchX);
  const gy = Array.from({ length: rows + 1 }, (_, j) => bottom + j * pitchY);
  const xs = [0, ...gx.slice(1, -1), gx[cols] + right];
  const ys = [0, ...gy.slice(1, -1), gy[rows] + topPad];
  const outline = [[], [], [], []];
  for (let col = 0; col < cols; col++)
    for (let row = 0; row < rows; row++) {
      const rect = [xs[col], ys[row], xs[col + 1], ys[row + 1]];
      const cx = (gx[col] + gx[col + 1]) / 2;
      const cy = (gy[row] + gy[row + 1]) / 2;
      const levels = POCKET.map(([z, inset, r]) =>
        at(roundedRect(cx, cy, POCKET_OPENING - 2 * inset, POCKET_OPENING - 2 * inset, r), z),
      );
      const topSides = rectAroundRounded(mesh, rect, levels[levels.length - 1], BASEPLATE_HEIGHT, true);
      const bottomSides = rectAroundRounded(mesh, rect, levels[0], 0, false);
      for (let i = 0; i < levels.length - 1; i++) mesh.wall(levels[i], levels[i + 1], false);
      // The tile's outside: only the sides of cells on its edge (bottom, right, top, left).
      const onEdge = [row === 0, col === cols - 1, row === rows - 1, col === 0];
      onEdge.forEach((edge, k) => {
        if (edge) outline[k].push([bottomSides[k], topSides[k]]);
      });
    }
  for (const side of outline)
    for (const [lower, upper] of side)
      for (let i = 0; i < lower.length - 1; i++) mesh.quad(lower[i], lower[i + 1], upper[i + 1], upper[i]);
  return mesh.triangles;
}

/**
 * A bin `w` × `d` cells of `pitchX` × `pitchY` mm, `units` × 7 mm tall, with `across` × `along` compartments.
 * Its corner is at the origin; it stands on its feet, one under each cell.
 */
export function bin({ w, d, units, across = 1, along = 1, pitchX = CELL, pitchY = CELL }) {
  const mesh = new Mesh();
  const outerW = w * pitchX - BIN_CLEARANCE;
  const outerD = d * pitchY - BIN_CLEARANCE;
  const height = units * HEIGHT_UNIT;
  const foot = CELL - BIN_CLEARANCE;
  for (let i = 0; i < w; i++)
    for (let j = 0; j < d; j++) solidLoft(mesh, (i + 0.5) * pitchX, (j + 0.5) * pitchY, foot, foot, FOOT);

  // The body: a cup whose bottom sinks a little into the feet, so the shells overlap.
  const cx = (w * pitchX) / 2;
  const cy = (d * pitchY) / 2;
  const bottomZ = FOOT_TOP - 0.15;
  const outer = roundedRect(cx, cy, outerW, outerD, BIN_RADIUS);
  const inner = roundedRect(cx, cy, outerW - 2 * WALL, outerD - 2 * WALL, Math.max(0.5, BIN_RADIUS - WALL));
  mesh.cap(at(outer, bottomZ), false);
  mesh.wall(at(outer, bottomZ), at(outer, height));
  mesh.band(at(outer, height), at(inner, height), true);
  mesh.wall(at(inner, FLOOR_TOP), at(inner, height), false);
  mesh.cap(at(inner, FLOOR_TOP), true);

  // Dividers, into the floor and walls a little, and a millimetre under the rim.
  const x0 = cx - outerW / 2 + WALL;
  const x1 = cx + outerW / 2 - WALL;
  const y0 = cy - outerD / 2 + WALL;
  const y1 = cy + outerD / 2 - WALL;
  const dividerTop = height - 1;
  for (let i = 1; i < across; i++) {
    const x = x0 + ((x1 - x0) * i) / across;
    mesh.box(x - DIVIDER / 2, y0 - 0.3, FLOOR_TOP - 0.2, x + DIVIDER / 2, y1 + 0.3, dividerTop);
  }
  for (let j = 1; j < along; j++) {
    const y = y0 + ((y1 - y0) * j) / along;
    mesh.box(x0 - 0.3, y - DIVIDER / 2, FLOOR_TOP - 0.2, x1 + 0.3, y + DIVIDER / 2, dividerTop);
  }
  return mesh.triangles;
}

/** Binary STL of triangles, with normals from their winding. */
export function stl(triangles, name = "thingport") {
  const buffer = new ArrayBuffer(84 + 50 * triangles.length);
  const view = new DataView(buffer);
  const header = `${name} - made with Thingport`.slice(0, 80);
  for (let i = 0; i < header.length; i++) view.setUint8(i, header.charCodeAt(i) & 0x7f);
  view.setUint32(80, triangles.length, true);
  let offset = 84;
  for (const [a, b, c] of triangles) {
    const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    const v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
    const n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    const length = Math.hypot(n[0], n[1], n[2]) || 1;
    for (const value of [n[0] / length, n[1] / length, n[2] / length, ...a, ...b, ...c]) {
      view.setFloat32(offset, value, true);
      offset += 4;
    }
    offset += 2;
  }
  return buffer;
}

// ---- plan.js ----

// The drawer's plan: its grid of cells, the baseplate cut into tiles a printer's bed takes, the bins on it, and the
// list of parts to print. Plain data, no drawing, so it can be checked without a page.


/** Room left around a part on the bed, for a skirt or brim. */
export const BED_MARGIN = 5;
/** The baseplate's border is cut no thinner than this; less is left as a gap along the drawer's wall. */
const MIN_BORDER = 1;

export const DEFAULT_PROJECT = {
  name: "",
  drawer: { width: 400, depth: 350, height: 70 },
  bed: { x: 256, y: 256 },
  /** "gridfinity": 42 mm cells, a border fills the rest. "stretch": cells widened to fill the drawer exactly. */
  cells: "gridfinity",
  /** Space left between the baseplate and the drawer's walls, in total across each way. */
  clearance: 1,
  /** Height of new bins, in 7 mm units. */
  units: 6,
  bins: [],
};

/** Cells and borders along one side of the drawer. */
function axis(length, clearance, mode) {
  const usable = Math.max(0, length - clearance);
  const count = Math.floor(usable / CELL);
  if (count < 1) return { count: 0, pitch: CELL, before: 0, after: 0, usable };
  if (mode === "stretch") return { count, pitch: usable / count, before: 0, after: 0, usable };
  const left = usable - count * CELL;
  // Too thin a border to print is left as a gap instead.
  const half = left / 2 >= MIN_BORDER ? left / 2 : 0;
  return { count, pitch: CELL, before: half, after: half, usable };
}

/** Cuts `count` cells into as few runs as the bed allows, the ends carrying the borders; null when one won't fit. */
function split(a, bedLength) {
  const room = bedLength - 2 * BED_MARGIN;
  for (let runs = 1; runs <= a.count; runs++) {
    const base = Math.floor(a.count / runs);
    const extra = a.count % runs;
    // The longer runs in the middle, where they carry no border.
    const sizes = Array.from({ length: runs }, () => base);
    for (let i = 0; i < extra; i++) sizes[Math.floor((runs - extra) / 2) + i] += 1;
    const lengths = sizes.map((n, i) => n * a.pitch + (i === 0 ? a.before : 0) + (i === runs - 1 ? a.after : 0));
    if (lengths.every((length) => length <= room + 1e-6)) {
      let start = 0;
      return sizes.map((n, i) => {
        const run = {
          start,
          count: n,
          before: i === 0 ? a.before : 0,
          after: i === runs - 1 ? a.after : 0,
          length: lengths[i],
        };
        start += n;
        return run;
      });
    }
  }
  return null;
}

const round = (value) => Math.round(value * 10) / 10;

/** A tile's size and borders turned a quarter anticlockwise: borders [left, right, front, back]. */
const turn = ({ cols, rows, pad: [left, right, front, back] }) => ({
  cols: rows,
  rows: cols,
  pad: [back, front, left, right],
});

/** One way round for each tile, so tiles that are the same part turned (a border left or right) print from one file. */
function canonical(tile) {
  let best = tile;
  let current = tile;
  for (let i = 0; i < 3; i++) {
    current = turn(current);
    if (JSON.stringify([current.cols, current.rows, current.pad]) < JSON.stringify([best.cols, best.rows, best.pad]))
      best = current;
  }
  return best;
}

/** Whether a part of `w` × `d` mm fits the bed, either way round. */
function fitsBed(w, d, bed) {
  const x = bed.x - 2 * BED_MARGIN;
  const y = bed.y - 2 * BED_MARGIN;
  return (w <= x && d <= y) || (w <= y && d <= x);
}

export function binSize(bin, grid) {
  return { width: bin.w * grid.x.pitch - 0.5, depth: bin.d * grid.y.pitch - 0.5, height: bin.units * HEIGHT_UNIT };
}

/** The whole plan, with what's wrong with it. */
export function planDrawer(project) {
  const { drawer, bed, cells, clearance } = project;
  const x = axis(drawer.width, clearance, cells);
  const y = axis(drawer.depth, clearance, cells);
  const grid = { x, y };
  const problems = [];
  if (!x.count || !y.count) {
    problems.push({
      kind: "small",
      text: `The drawer needs to be at least ${CELL + clearance} mm each way for one cell.`,
    });
    return { grid, tiles: [], tileRuns: { x: [], y: [] }, parts: [], bins: [], problems };
  }
  const runsX = split(x, bed.x);
  const runsY = split(y, bed.y);
  if (!runsX || !runsY)
    problems.push({ kind: "bed", text: "A single cell and its border don't fit the bed: make the bed bigger." });

  // Tiles, and the kinds of tile, each with how many of it.
  const tiles = [];
  const kinds = new Map();
  for (const rx of runsX ?? [])
    for (const ry of runsY ?? []) {
      const shape = canonical({
        cols: rx.count,
        rows: ry.count,
        pad: [rx.before, rx.after, ry.before, ry.after].map(round),
      });
      const key = `${shape.cols}x${shape.rows}|${shape.pad.join(",")}`;
      if (!kinds.has(key)) kinds.set(key, { key, ...shape, count: 0 });
      kinds.get(key).count++;
      tiles.push({ col: rx.start, row: ry.start, cols: rx.count, rows: ry.count, key });
    }
  // Letters for the kinds, in the order a reader meets them from the front left.
  [...kinds.values()].forEach((kind, i) => (kind.letter = String.fromCharCode(65 + i)));

  // Bins: inside the grid, not overlapping, printable and short enough for the drawer.
  const taken = new Map();
  const bins = project.bins.map((b) => {
    const size = binSize(b, grid);
    const issues = [];
    if (b.x < 0 || b.y < 0 || b.x + b.w > x.count || b.y + b.d > y.count) issues.push("is outside the grid");
    for (let i = b.x; i < b.x + b.w; i++)
      for (let j = b.y; j < b.y + b.d; j++) {
        const cell = `${i},${j}`;
        if (taken.has(cell) && !issues.includes("overlaps another bin")) issues.push("overlaps another bin");
        taken.set(cell, b.id);
      }
    if (!fitsBed(size.width, size.depth, bed)) issues.push("is too big for the bed");
    if (size.height > drawer.height) issues.push("is taller than the drawer");
    return { ...b, size, issues };
  });
  for (const b of bins)
    if (b.issues.length) problems.push({ kind: "bin", id: b.id, text: `A ${b.w}×${b.d} bin ${listText(b.issues)}.` });

  const binKinds = new Map();
  for (const b of bins) {
    if (b.issues.length) continue;
    const key = `${b.w}x${b.d}-${b.units}u-${b.across}x${b.along}`;
    if (!binKinds.has(key))
      binKinds.set(key, { key, w: b.w, d: b.d, units: b.units, across: b.across, along: b.along, count: 0 });
    binKinds.get(key).count++;
  }

  const parts = [
    ...[...kinds.values()].map((kind) => ({
      type: "tile",
      key: kind.key,
      letter: kind.letter,
      count: kind.count,
      cols: kind.cols,
      rows: kind.rows,
      pad: kind.pad,
      name: `Baseplate tile ${kind.letter}: ${kind.cols}×${kind.rows}`,
      detail: borderText(kind.pad),
      file: `${kind.count}x-baseplate-${kind.letter.toLowerCase()}-${kind.cols}x${kind.rows}.stl`,
    })),
    ...[...binKinds.values()].map((kind) => ({
      type: "bin",
      key: kind.key,
      count: kind.count,
      w: kind.w,
      d: kind.d,
      units: kind.units,
      across: kind.across,
      along: kind.along,
      name: `Bin ${kind.w}×${kind.d}, ${kind.units}u`,
      detail: kind.across * kind.along > 1 ? `${kind.across}×${kind.along} compartments` : "",
      file: `${kind.count}x-bin-${kind.w}x${kind.d}-${kind.units}u${kind.across * kind.along > 1 ? `-${kind.across}x${kind.along}` : ""}.stl`,
    })),
  ];
  return { grid, tiles, tileRuns: { x: runsX ?? [], y: runsY ?? [] }, parts, bins, problems };
}

/** A tile's borders, by how many sides and how wide: it's turned to fit, so which side is left to the layout. */
function borderText(pad) {
  const sides = pad.filter((p) => p > 0);
  if (!sides.length) return "";
  const widths = [...new Set(sides)];
  const across = pad[0] > 0 && pad[1] > 0;
  const along = pad[2] > 0 && pad[3] > 0;
  const where = sides.length === 1 ? "on one side" : across || along ? "on opposite sides" : "on two sides at a corner";
  return widths.length === 1
    ? `${widths[0]} mm border ${sides.length > 2 ? `on ${sides.length} sides` : where}`
    : `borders of ${listText(widths.map((w) => `${w}`))} mm`;
}

const listText = (items) =>
  items.length < 2 ? items.join("") : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;

/** Where each tile goes, as letters on the drawer's grid of tiles, back row first as one looks down into it. */
export function tileMap(plan) {
  const letters = new Map(plan.parts.filter((p) => p.type === "tile").map((p) => [p.key, p.letter]));
  const rows = [];
  for (const ry of [...plan.tileRuns.y].reverse()) {
    rows.push(
      plan.tileRuns.x
        .map((rx) => letters.get(plan.tiles.find((t) => t.col === rx.start && t.row === ry.start)?.key) ?? "?")
        .join(" "),
    );
  }
  return rows.join("\n");
}

/** The model's description: what it's for, what to print and how many, and how it goes together. */
export function description(project, plan) {
  const { drawer, bed } = project;
  const { x, y } = plan.grid;
  const tiles = plan.parts.filter((p) => p.type === "tile");
  const bins = plan.parts.filter((p) => p.type === "bin");
  const count = (list) => list.reduce((sum, p) => sum + p.count, 0);
  const cellText =
    project.cells === "stretch"
      ? `${x.count} × ${y.count} cells stretched to ${round(x.pitch)} × ${round(y.pitch)} mm to fill the drawer exactly (bins are made to match)`
      : `${x.count} × ${y.count} Gridfinity cells of 42 mm`;
  const lines = [
    `A Gridfinity organizer for a ${drawer.width} × ${drawer.depth} × ${drawer.height} mm drawer, cut to print on a ${bed.x} × ${bed.y} mm bed.`,
    "",
    `${cellText}. The baseplate leaves ${project.clearance} mm of room to the walls${
      project.cells === "gridfinity" && (x.before > 0 || y.before > 0) ? " and fills the rest with a flat border" : ""
    }.`,
    "",
    "## What to print",
    "",
    "| Part | Print | File |",
    "| --- | ---: | --- |",
    ...plan.parts.map((p) => `| ${p.name}${p.detail ? ` (${p.detail})` : ""} | ${p.count} | \`${p.file}\` |`),
    "",
    `In all: ${count(tiles)} baseplate tile${count(tiles) === 1 ? "" : "s"}${
      bins.length ? ` and ${count(bins)} bin${count(bins) === 1 ? "" : "s"}` : ""
    }. Each file's name starts with how many of it to print.`,
    "",
    "## Putting it together",
    "",
    "Lay the baseplate tiles in the drawer as below, looking down into it with its front at the bottom, each turned so its border meets the drawer's wall. They lie side by side, held by the walls; no glue is needed.",
    "",
    "```",
    tileMap(plan),
    "```",
  ];
  if (bins.length) {
    lines.push("", "Then drop the bins into the pockets, as in the picture.");
  }
  lines.push(
    "",
    "Bins are " +
      (bins.length ? `${HEIGHT_UNIT} mm a height unit (u), ` : "") +
      "printed without supports, open side up; tiles print flat as they lie.",
  );
  return lines.join("\n");
}

// ---- render.js ----

// A small renderer for the parts' previews: the triangles turned to a view, sorted back to front and filled with flat
// shading on a canvas. Enough to see a part's shape without a 3D library.

const span = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

function parseColor(color) {
  const hex = /^#([0-9a-f]{6})$/i.exec(color.trim());
  if (hex) return [0, 2, 4].map((i) => parseInt(hex[1].slice(i, i + 2), 16));
  const rgb = /rgba?\(([^)]+)\)/.exec(color);
  if (rgb)
    return rgb[1]
      .split(",")
      .slice(0, 3)
      .map((v) => Number(v));
  return [90, 150, 90];
}

/**
 * Draws `triangles` on `canvas`, seen from `azimuth` degrees round and `elevation` degrees up (90 is straight down),
 * filling the canvas with the part.
 */
export function renderMesh(canvas, triangles, { azimuth = -35, elevation = 32, color = "#4caf50", padding = 6 } = {}) {
  const ratio = window.devicePixelRatio || 1;
  const width = canvas.clientWidth || canvas.width;
  const height = canvas.clientHeight || canvas.height;
  if (canvas.width !== Math.round(width * ratio) || canvas.height !== Math.round(height * ratio)) {
    canvas.width = Math.round(width * ratio);
    canvas.height = Math.round(height * ratio);
  }
  const ctx = canvas.getContext("2d");
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.clearRect(0, 0, width, height);
  if (!triangles.length) return;

  const a = (azimuth * Math.PI) / 180;
  const e = (elevation * Math.PI) / 180;
  const [ca, sa, ce, se] = [Math.cos(a), Math.sin(a), Math.cos(e), Math.sin(e)];
  // To the view: x across the screen, y up it, z towards the viewer.
  const view = ([x, y, z]) => {
    const rx = x * ca - y * sa;
    const ry = x * sa + y * ca;
    return [rx, z * ce + ry * se, -ry * ce + z * se];
  };
  const projected = triangles.map((t) => t.map(view));
  let minX = Infinity,
    maxX = -Infinity,
    minY = Infinity,
    maxY = -Infinity;
  for (const t of projected)
    for (const [x, y] of t) {
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    }
  const scale = Math.min((width - 2 * padding) / (maxX - minX || 1), (height - 2 * padding) / (maxY - minY || 1));
  const ox = (width - (maxX - minX) * scale) / 2;
  const oy = (height - (maxY - minY) * scale) / 2;
  const base = parseColor(color);
  const light = [-0.45, 0.6, 0.66];

  // Sorting by a face's middle goes wrong where a big face (a bin's floor) lies beside small ones (its dividers), so big
  // faces are cut into pieces no longer than this before they're sorted.
  const longest = Math.max(maxX - minX, maxY - minY) / 12;
  const faces = [];
  const add = (p, q, r, shade, depth = 0) => {
    const edges = [
      [p, q, r],
      [q, r, p],
      [r, p, q],
    ];
    const [a, b, c] = edges.reduce((worst, edge) => (span(edge[0], edge[1]) > span(worst[0], worst[1]) ? edge : worst));
    if (depth < 6 && span(a, b) > longest) {
      const m = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
      add(a, m, c, shade, depth + 1);
      add(m, b, c, shade, depth + 1);
      return;
    }
    faces.push({ points: [p, q, r], depth: (p[2] + q[2] + r[2]) / 3, shade });
  };
  for (const [p, q, r] of projected) {
    const u = [q[0] - p[0], q[1] - p[1], q[2] - p[2]];
    const v = [r[0] - p[0], r[1] - p[1], r[2] - p[2]];
    const n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
    const length = Math.hypot(n[0], n[1], n[2]);
    // Facing away: hidden behind the faces that face the viewer.
    if (!length || n[2] <= 0) continue;
    add(p, q, r, 0.38 + 0.62 * Math.max(0, (n[0] * light[0] + n[1] * light[1] + n[2] * light[2]) / length));
  }
  faces.sort((f, g) => f.depth - g.depth);
  for (const { points, shade } of faces) {
    ctx.beginPath();
    points.forEach(([x, y], i) => {
      const sx = ox + (x - minX) * scale;
      const sy = height - (oy + (y - minY) * scale);
      if (i) ctx.lineTo(sx, sy);
      else ctx.moveTo(sx, sy);
    });
    ctx.closePath();
    const fill = `rgb(${base.map((c) => Math.round(Math.min(255, c * shade))).join(",")})`;
    ctx.fillStyle = fill;
    // A hairline of the same colour hides the seams between neighbouring triangles.
    ctx.strokeStyle = fill;
    ctx.lineWidth = 0.6;
    ctx.fill();
    ctx.stroke();
  }
}

// ---- ui.js ----

// The drawer builder's window: the drawer and printer on the left, the drawer seen from above in the middle (drag to
// draw a bin, drag one to move it), and the parts to print on the right, with "Save to Thingport", which keeps the
// whole drawer as one model: every part a file, and how many of each to print in its description.


const SVGNS = "http://www.w3.org/2000/svg";
const BEDS = [
  ["Bambu Lab A1 mini", 180, 180],
  ["Prusa MINI", 180, 180],
  ["Creality Ender-3", 220, 220],
  ["Prusa MK4 / Core One", 250, 210],
  ["Bambu Lab A1, P1, X1", 256, 256],
  ["Creality K1 Max", 300, 300],
  ["Bambu Lab H2D", 325, 320],
  ["Prusa XL", 360, 360],
];
const MAX_UNITS = 20;
const SAVE_DEBOUNCE_MS = 500;

export default async function mount(thingport) {
  const { root, theme, storage, models, ui } = thingport;
  const $ = (id) => root.querySelector(`#gfd-${id}`);
  const shell = root.querySelector(".gfd");
  const colours = {
    bg: theme.background,
    panel: theme.paper,
    divider: theme.divider,
    text: theme.text,
    muted: theme.textSecondary,
    accent: theme.primary,
    // What reads on the accent, which Thingport picks per accent colour: white for most, dark for the light ones
    // like amber. The fallback keeps an older Thingport, which didn't hand it over, close to right.
    "accent-ink": theme.primaryContrast ?? "#ffffff",
    danger: theme.error,
    font: theme.fontFamily,
  };
  for (const [name, value] of Object.entries(colours)) shell.style.setProperty(`--${name}`, value);
  const binColour = theme.primary;
  const tileColour = theme.mode === "dark" ? "#8a8f98" : "#9aa0a6";

  // ---- the project, kept for the user ------------------------------------------------------------------------
  let project = structuredClone(DEFAULT_PROJECT);
  try {
    const saved = await storage.get("project");
    if (saved && typeof saved === "object") project = { ...project, ...saved };
  } catch {
    // Starts from the defaults.
  }
  let persistTimer = 0;
  const persist = () => {
    clearTimeout(persistTimer);
    persistTimer = setTimeout(() => void storage.set("project", project).catch(() => undefined), SAVE_DEBOUNCE_MS);
  };
  let nextId = project.bins.reduce((max, b) => Math.max(max, Number(String(b.id).replace(/\D/g, "")) || 0), 0) + 1;
  const newId = () => `b${nextId++}`;

  let plan = planDrawer(project);
  let selected = null;
  let viewed = null;
  let view = { azimuth: -35, elevation: 32 };
  let lastSaved = null;

  // ---- settings ----------------------------------------------------------------------------------------------
  const preset = $("bedPreset");
  preset.innerHTML =
    `<option value="">Bed size…</option>` +
    BEDS.map(([name, x, y], i) => `<option value="${i}">${name} (${x} × ${y})</option>`).join("");
  preset.addEventListener("change", () => {
    const bed = BEDS[Number(preset.value)];
    if (bed) {
      project.bed = { x: bed[1], y: bed[2] };
      update();
    }
    preset.value = "";
  });

  const numberField = (id, read, write, { min, max }) => {
    const input = $(id);
    input.value = String(read());
    input.addEventListener("change", () => {
      const value = Number(input.value);
      if (Number.isFinite(value) && value >= min && value <= max) write(value);
      input.value = String(read());
      update();
    });
  };
  numberField(
    "width",
    () => project.drawer.width,
    (v) => (project.drawer.width = v),
    { min: 40, max: 2000 },
  );
  numberField(
    "depth",
    () => project.drawer.depth,
    (v) => (project.drawer.depth = v),
    { min: 40, max: 2000 },
  );
  numberField(
    "height",
    () => project.drawer.height,
    (v) => (project.drawer.height = v),
    { min: 10, max: 500 },
  );
  numberField(
    "bedX",
    () => project.bed.x,
    (v) => (project.bed.x = v),
    { min: 60, max: 1000 },
  );
  numberField(
    "bedY",
    () => project.bed.y,
    (v) => (project.bed.y = v),
    { min: 60, max: 1000 },
  );
  numberField(
    "clearance",
    () => project.clearance,
    (v) => (project.clearance = v),
    { min: 0, max: 10 },
  );
  const name = $("name");
  name.value = project.name;
  name.addEventListener("input", () => {
    project.name = name.value.slice(0, 120);
    persist();
  });
  $("cells").addEventListener("click", (event) => {
    const button = event.target.closest("button[data-value]");
    if (!button) return;
    project.cells = button.dataset.value;
    update();
  });
  const maxUnits = () => Math.max(1, Math.min(MAX_UNITS, Math.floor(project.drawer.height / HEIGHT_UNIT)));
  $("unitsDown").addEventListener("click", () => {
    project.units = Math.max(1, project.units - 1);
    update();
  });
  $("unitsUp").addEventListener("click", () => {
    project.units = Math.min(maxUnits(), project.units + 1);
    update();
  });

  // ---- the drawer from above ---------------------------------------------------------------------------------
  // In millimetres, the drawer's front left corner at the bottom left, as one looks down into it.
  const geometryOf = () => {
    const { x, y } = plan.grid;
    const left = project.clearance / 2 + x.before;
    const front = project.clearance / 2 + y.before;
    return { x, y, left, front, W: project.drawer.width, D: project.drawer.depth };
  };
  const cellRect = (g, col, row, w = 1, d = 1) => ({
    x: g.left + col * g.x.pitch,
    y: g.D - (g.front + (row + d) * g.y.pitch),
    width: w * g.x.pitch,
    height: d * g.y.pitch,
  });
  const svgEl = (tag, attrs, parent) => {
    const node = document.createElementNS(SVGNS, tag);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
    if (parent) parent.appendChild(node);
    return node;
  };

  let svg = null;
  let drag = null;
  const freshBins = new Set();

  function drawLayout() {
    const stage = $("stage");
    const g = geometryOf();
    if (!g.x.count || !g.y.count) {
      stage.innerHTML = `<div class="gfd-empty"><strong>No cell fits</strong>${plan.problems[0]?.text ?? ""}</div>`;
      svg = null;
      return;
    }
    const pad = Math.max(g.W, g.D) * 0.02;
    // Room below for the "Front" mark.
    const below = pad + 18;
    svg = svgEl("svg", {
      viewBox: `${-pad} ${-pad} ${g.W + 2 * pad} ${g.D + pad + below}`,
      role: "application",
      tabindex: 0,
      "aria-label": `Drawer layout, ${g.x.count} by ${g.y.count} cells, ${project.bins.length} bins. Drag to draw a bin, or press N to add one; [ and ] pick a bin, the arrow keys move it, Shift and the arrow keys size it, and Delete removes it.`,
    });
    // The drawer, then the baseplate's tiles and cells.
    svgEl(
      "rect",
      {
        x: 0,
        y: 0,
        width: g.W,
        height: g.D,
        rx: 4,
        fill: "color-mix(in srgb, var(--text) 6%, transparent)",
        stroke: "var(--line)",
      },
      svg,
    );
    const plate = svgEl("g", {}, svg);
    const letters = new Map(plan.parts.filter((p) => p.type === "tile").map((p) => [p.key, p.letter]));
    for (const t of plan.tiles) {
      const rx = plan.tileRuns.x.find((r) => r.start === t.col);
      const ry = plan.tileRuns.y.find((r) => r.start === t.row);
      const outer = cellRect(g, t.col, t.row, t.cols, t.rows);
      const x0 = outer.x - rx.before;
      const y0 = outer.y - ry.after;
      svgEl(
        "rect",
        {
          x: x0,
          y: y0,
          width: outer.width + rx.before + rx.after,
          height: outer.height + ry.before + ry.after,
          rx: 2,
          fill: `color-mix(in srgb, ${tileColour} 22%, transparent)`,
          stroke: tileColour,
          "stroke-dasharray": "4 3",
          "stroke-width": 1,
        },
        plate,
      );
      svgEl(
        "text",
        { x: x0 + 4, y: y0 + 13, "font-size": 11, "font-weight": 700, fill: tileColour },
        plate,
      ).textContent = letters.get(t.key) ?? "";
    }
    for (let col = 0; col < g.x.count; col++)
      for (let row = 0; row < g.y.count; row++) {
        const r = cellRect(g, col, row);
        svgEl(
          "rect",
          { class: "gfd-cell", x: r.x + 1, y: r.y + 1, width: r.width - 2, height: r.height - 2, rx: 4 },
          plate,
        );
      }
    // The bins.
    const layer = svgEl("g", {}, svg);
    for (const b of plan.bins) {
      const r = cellRect(g, b.x, b.y, b.w, b.d);
      const bad = b.issues.length > 0;
      const colour = bad ? "var(--danger)" : binColour;
      const group = svgEl("g", { class: `gfd-bin${freshBins.has(b.id) ? " gfd-enter" : ""}`, "data-id": b.id }, layer);
      svgEl(
        "rect",
        {
          x: r.x + 2.5,
          y: r.y + 2.5,
          width: r.width - 5,
          height: r.height - 5,
          rx: 5,
          fill: `color-mix(in srgb, ${colour} ${b.id === selected ? 42 : 26}%, transparent)`,
          stroke: colour,
          "stroke-width": b.id === selected ? 3 : 1.5,
        },
        group,
      );
      // Its compartments.
      for (let i = 1; i < b.across; i++) {
        const x = r.x + (r.width * i) / b.across;
        svgEl(
          "line",
          { x1: x, y1: r.y + 7, x2: x, y2: r.y + r.height - 7, stroke: colour, "stroke-width": 1, opacity: 0.6 },
          group,
        );
      }
      for (let j = 1; j < b.along; j++) {
        const y = r.y + (r.height * j) / b.along;
        svgEl(
          "line",
          { x1: r.x + 7, y1: y, x2: r.x + r.width - 7, y2: y, stroke: colour, "stroke-width": 1, opacity: 0.6 },
          group,
        );
      }
      const label = svgEl(
        "text",
        {
          x: r.x + r.width / 2,
          y: r.y + r.height / 2,
          "text-anchor": "middle",
          "dominant-baseline": "central",
          "font-size": Math.min(14, r.width / 4),
          "font-weight": 700,
          fill: "var(--text)",
          "pointer-events": "none",
        },
        group,
      );
      // The size where there's room for it; a single cell has room for the height alone.
      label.textContent = r.width > 70 ? `${b.w}×${b.d} · ${b.units}u` : `${b.units}u`;
      svgEl("title", {}, group).textContent = bad ? b.issues.join(", ") : `${b.w}×${b.d} bin, ${b.units}u`;
    }
    freshBins.clear();
    // The bin being drawn or moved.
    svgEl(
      "rect",
      {
        id: "gfd-ghost",
        x: 0,
        y: 0,
        width: 0,
        height: 0,
        rx: 5,
        fill: "none",
        stroke: "var(--accent)",
        "stroke-width": 2,
        "stroke-dasharray": "6 4",
        visibility: "hidden",
      },
      svg,
    );
    svgEl(
      "text",
      { x: g.W / 2, y: g.D + 14, "text-anchor": "middle", "font-size": 11, fill: "var(--muted)" },
      svg,
    ).textContent = "Front";
    stage.replaceChildren(svg);
    svg.addEventListener("pointerdown", onDown);
    svg.addEventListener("keydown", onKey);
  }

  /** The cell under a pointer, in grid units (fractions included). */
  function cellAt(event) {
    const g = geometryOf();
    const point = svg.createSVGPoint();
    point.x = event.clientX;
    point.y = event.clientY;
    const p = point.matrixTransform(svg.getScreenCTM().inverse());
    return { col: (p.x - g.left) / g.x.pitch, row: (g.D - p.y - g.front) / g.y.pitch };
  }
  const clampCell = (value, count) => Math.max(0, Math.min(count - 1, Math.floor(value)));
  const occupied = (except) => {
    const cells = new Set();
    for (const b of project.bins)
      if (b.id !== except)
        for (let i = b.x; i < b.x + b.w; i++) for (let j = b.y; j < b.y + b.d; j++) cells.add(`${i},${j}`);
    return cells;
  };
  const free = (rect, except) => {
    const cells = occupied(except);
    for (let i = rect.x; i < rect.x + rect.w; i++)
      for (let j = rect.y; j < rect.y + rect.d; j++) if (cells.has(`${i},${j}`)) return false;
    return true;
  };
  const showGhost = (rect, ok) => {
    const ghost = svg.querySelector("#gfd-ghost");
    const r = cellRect(geometryOf(), rect.x, rect.y, rect.w, rect.d);
    for (const [key, value] of Object.entries({ x: r.x + 2.5, y: r.y + 2.5, width: r.width - 5, height: r.height - 5 }))
      ghost.setAttribute(key, value);
    ghost.setAttribute("stroke", ok ? "var(--accent)" : "var(--danger)");
    ghost.setAttribute("visibility", "visible");
  };

  function onDown(event) {
    if (event.button !== 0) return;
    const g = geometryOf();
    const at = cellAt(event);
    const binNode = event.target.closest(".gfd-bin");
    svg.setPointerCapture(event.pointerId);
    if (binNode) {
      const b = project.bins.find((candidate) => candidate.id === binNode.dataset.id);
      selected = b.id;
      drag = {
        kind: "move",
        bin: b,
        grab: { col: at.col - b.x, row: at.row - b.y },
        rect: { x: b.x, y: b.y, w: b.w, d: b.d },
        moved: false,
      };
      update();
    } else {
      const start = { col: clampCell(at.col, g.x.count), row: clampCell(at.row, g.y.count) };
      drag = { kind: "draw", start, rect: { x: start.col, y: start.row, w: 1, d: 1 } };
      showGhost(drag.rect, free(drag.rect));
    }
    svg.addEventListener("pointermove", onMove);
    svg.addEventListener("pointerup", onUp, { once: true });
  }

  function onMove(event) {
    if (!drag) return;
    const g = geometryOf();
    const at = cellAt(event);
    if (drag.kind === "draw") {
      const col = clampCell(at.col, g.x.count);
      const row = clampCell(at.row, g.y.count);
      drag.rect = {
        x: Math.min(col, drag.start.col),
        y: Math.min(row, drag.start.row),
        w: Math.abs(col - drag.start.col) + 1,
        d: Math.abs(row - drag.start.row) + 1,
      };
      showGhost(drag.rect, free(drag.rect));
    } else {
      const x = Math.max(0, Math.min(g.x.count - drag.bin.w, Math.round(at.col - drag.grab.col)));
      const y = Math.max(0, Math.min(g.y.count - drag.bin.d, Math.round(at.row - drag.grab.row)));
      if (x !== drag.rect.x || y !== drag.rect.y) drag.moved = true;
      drag.rect = { ...drag.rect, x, y };
      if (drag.moved) showGhost(drag.rect, free(drag.rect, drag.bin.id));
    }
  }

  function onUp() {
    svg?.removeEventListener("pointermove", onMove);
    const done = drag;
    drag = null;
    if (!done) return;
    if (done.kind === "draw") {
      if (!free(done.rect)) {
        ui.toast("That's over another bin", "warning");
        return update();
      }
      const units = Math.min(project.units, maxUnits());
      const b = { id: newId(), ...done.rect, units, across: 1, along: 1 };
      project.bins.push(b);
      freshBins.add(b.id);
      selected = b.id;
      update();
    } else if (done.moved) {
      if (free(done.rect, done.bin.id)) Object.assign(done.bin, { x: done.rect.x, y: done.rect.y });
      else ui.toast("That's over another bin", "warning");
      update();
    }
  }

  // By keyboard: N adds a bin, [ and ] pick one, the arrows move it a cell, Shift and the arrows size it.
  const STEPS = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] };
  function onKey(event) {
    const g = geometryOf();
    const current = project.bins.find((b) => b.id === selected);
    const key = event.key;
    let handled = true;
    if ((key === "Delete" || key === "Backspace") && current) removeBin(current.id);
    else if (key === "Escape" && current) selected = null;
    else if (key === "n" || key === "N") {
      const cells = occupied(null);
      let spot = null;
      for (let row = 0; row < g.y.count && !spot; row++)
        for (let col = 0; col < g.x.count && !spot; col++) if (!cells.has(`${col},${row}`)) spot = { x: col, y: row };
      if (!spot) ui.toast("Every cell has a bin", "info");
      else {
        const b = { id: newId(), ...spot, w: 1, d: 1, units: Math.min(project.units, maxUnits()), across: 1, along: 1 };
        project.bins.push(b);
        freshBins.add(b.id);
        selected = b.id;
      }
    } else if ((key === "[" || key === "]") && project.bins.length) {
      const index = project.bins.findIndex((b) => b.id === selected);
      const next = index < 0 ? 0 : (index + (key === "]" ? 1 : -1) + project.bins.length) % project.bins.length;
      selected = project.bins[next].id;
    } else if (STEPS[key] && current) {
      const [dx, dy] = STEPS[key];
      const rect = event.shiftKey
        ? { x: current.x, y: current.y, w: current.w + dx, d: current.d + dy }
        : { x: current.x + dx, y: current.y + dy, w: current.w, d: current.d };
      const inside =
        rect.w >= 1 &&
        rect.d >= 1 &&
        rect.x >= 0 &&
        rect.y >= 0 &&
        rect.x + rect.w <= g.x.count &&
        rect.y + rect.d <= g.y.count;
      if (inside && free(rect, current.id)) {
        Object.assign(current, rect);
        current.across = Math.min(current.across, current.w * 3);
        current.along = Math.min(current.along, current.d * 3);
      }
    } else handled = false;
    if (!handled) return;
    event.preventDefault();
    update();
    // Drawn afresh, so the keys go on working.
    svg?.focus();
  }

  function removeBin(id) {
    project.bins = project.bins.filter((b) => b.id !== id);
    if (selected === id) selected = null;
    update();
  }

  // ---- the selected bin --------------------------------------------------------------------------------------
  function stepper(label, value, min, max, set) {
    const wrap = document.createElement("span");
    wrap.className = "gfd-pair";
    const name = document.createElement("span");
    name.className = "gfd-label";
    name.textContent = label;
    const box = document.createElement("span");
    box.className = "gfd-stepper";
    box.setAttribute("role", "group");
    box.setAttribute("aria-label", label);
    const down = document.createElement("button");
    down.type = "button";
    down.textContent = "−";
    down.setAttribute("aria-label", `Fewer: ${label}`);
    down.disabled = value <= min;
    down.addEventListener("click", () => set(value - 1));
    const out = document.createElement("output");
    out.textContent = String(value);
    const up = document.createElement("button");
    up.type = "button";
    up.textContent = "+";
    up.setAttribute("aria-label", `More: ${label}`);
    up.disabled = value >= max;
    up.addEventListener("click", () => set(value + 1));
    box.append(down, out, up);
    wrap.append(name, box);
    return wrap;
  }

  function drawSelected() {
    const host = $("selected");
    const b = project.bins.find((candidate) => candidate.id === selected);
    const planned = plan.bins.find((candidate) => candidate.id === selected);
    if (!b || !planned) {
      host.hidden = true;
      return;
    }
    host.hidden = false;
    host.replaceChildren();
    const title = document.createElement("strong");
    const { width, depth, height } = planned.size;
    title.textContent = `Bin ${b.w}×${b.d}`;
    const size = document.createElement("span");
    size.className = "gfd-hint";
    size.textContent = `${width.toFixed(1)} × ${depth.toFixed(1)} × ${height} mm`;
    const set = (key) => (value) => {
      b[key] = value;
      update();
    };
    const remove = document.createElement("button");
    remove.className = "gfd-btn gfd-danger";
    remove.type = "button";
    remove.textContent = "Delete";
    remove.addEventListener("click", () => removeBin(b.id));
    const spacer = document.createElement("span");
    spacer.className = "gfd-spacer";
    host.append(
      title,
      size,
      stepper("Height (u)", b.units, 1, maxUnits(), set("units")),
      stepper("Across", b.across, 1, Math.max(1, b.w * 3), set("across")),
      stepper("Along", b.along, 1, Math.max(1, b.d * 3), set("along")),
      spacer,
      remove,
    );
  }

  // ---- parts -------------------------------------------------------------------------------------------------
  const meshes = new Map();
  /** A part's triangles, made once for each shape. */
  function meshOf(part) {
    const { x, y } = plan.grid;
    const key = `${part.type}|${part.key}|${x.pitch.toFixed(3)}|${y.pitch.toFixed(3)}`;
    if (!meshes.has(key)) {
      meshes.set(
        key,
        part.type === "tile"
          ? baseplateTile({ cols: part.cols, rows: part.rows, pitchX: x.pitch, pitchY: y.pitch, pad: part.pad })
          : bin({
              w: part.w,
              d: part.d,
              units: part.units,
              across: part.across,
              along: part.along,
              pitchX: x.pitch,
              pitchY: y.pitch,
            }),
      );
    }
    return meshes.get(key);
  }
  const partColour = (part) => (part.type === "tile" ? tileColour : binColour);
  /** The parts listed last time: only the ones new to the list rise into it. */
  let listed = new Set();

  function drawParts() {
    const list = $("list");
    list.replaceChildren();
    const tiles = plan.parts.filter((p) => p.type === "tile").reduce((n, p) => n + p.count, 0);
    const bins = plan.parts.filter((p) => p.type === "bin").reduce((n, p) => n + p.count, 0);
    $("count").textContent = plan.parts.length
      ? `${tiles} tile${tiles === 1 ? "" : "s"}, ${bins} bin${bins === 1 ? "" : "s"}`
      : "";
    if (!plan.parts.some((p) => p.key === viewed?.key)) viewed = plan.parts[0] ?? null;
    plan.parts.forEach((part, index) => {
      const item = document.createElement("li");
      item.className = listed.has(part.key) ? "gfd-part gfd-still" : "gfd-part";
      item.tabIndex = 0;
      item.style.animationDelay = `${Math.min(index * 30, 240)}ms`;
      item.setAttribute("aria-current", String(part.key === viewed?.key));
      item.setAttribute("aria-label", `${part.name}, print ${part.count}`);
      const thumb = document.createElement("canvas");
      thumb.setAttribute("aria-hidden", "true");
      const text = document.createElement("span");
      text.className = "gfd-part-name";
      text.textContent = part.name;
      if (part.detail) {
        const small = document.createElement("small");
        small.textContent = part.detail;
        text.appendChild(small);
      }
      const qty = document.createElement("span");
      qty.className = "gfd-qty";
      qty.innerHTML = `${part.count}<small>×</small>`;
      const save = document.createElement("button");
      save.type = "button";
      save.className = "gfd-icon-btn";
      save.title = `Download ${part.file}`;
      save.setAttribute("aria-label", `Download ${part.file}`);
      save.innerHTML =
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 3v12m0 0-4-4m4 4 4-4M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2"/></svg>';
      save.addEventListener("click", (event) => {
        event.stopPropagation();
        thingport.download({ name: part.file, data: stl(meshOf(part), part.name), type: "model/stl" });
      });
      const look = () => {
        viewed = part;
        list.querySelectorAll(".gfd-part").forEach((node) => node.setAttribute("aria-current", String(node === item)));
        drawView();
      };
      item.addEventListener("click", look);
      item.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          look();
        }
      });
      item.append(thumb, text, qty, save);
      list.appendChild(item);
      // Drawn once it's in the page and has a size.
      requestAnimationFrame(() => renderMesh(thumb, meshOf(part), { color: partColour(part), padding: 2 }));
    });
    listed = new Set(plan.parts.map((p) => p.key));
    const problems = $("problems");
    problems.hidden = plan.problems.length === 0;
    problems.innerHTML = plan.problems.map((p) => `<li>${escapeHtml(p.text)}</li>`).join("");
    $("save").disabled = !plan.parts.length;
    drawView();
  }

  function drawView() {
    const canvas = $("viewCanvas");
    $("viewName").textContent = viewed ? `${viewed.name}${viewed.detail ? ` · ${viewed.detail}` : ""}` : "";
    requestAnimationFrame(() =>
      renderMesh(canvas, viewed ? meshOf(viewed) : [], { ...view, color: viewed ? partColour(viewed) : binColour }),
    );
  }

  // Dragging the big view turns the part.
  const viewBox = $("view");
  viewBox.addEventListener("pointerdown", (event) => {
    viewBox.setPointerCapture(event.pointerId);
    const start = { x: event.clientX, y: event.clientY, ...view };
    const move = (e) => {
      view = {
        azimuth: start.azimuth + (e.clientX - start.x) * 0.6,
        elevation: Math.max(5, Math.min(89, start.elevation + (e.clientY - start.y) * 0.4)),
      };
      drawView();
    };
    viewBox.addEventListener("pointermove", move);
    viewBox.addEventListener("pointerup", () => viewBox.removeEventListener("pointermove", move), { once: true });
  });

  // ---- facts and controls ------------------------------------------------------------------------------------
  function syncControls() {
    for (const button of $("cells").querySelectorAll("button"))
      button.setAttribute("aria-pressed", String(button.dataset.value === project.cells));
    for (const [id, value] of [
      ["width", project.drawer.width],
      ["depth", project.drawer.depth],
      ["height", project.drawer.height],
      ["bedX", project.bed.x],
      ["bedY", project.bed.y],
      ["clearance", project.clearance],
    ])
      if (root.ownerDocument.activeElement !== $(id)) $(id).value = String(value);
    project.units = Math.min(project.units, maxUnits());
    $("units").textContent = `${project.units}u`;
    $("unitsMm").textContent = `${project.units * HEIGHT_UNIT} mm tall`;
    $("unitsDown").disabled = project.units <= 1;
    $("unitsUp").disabled = project.units >= maxUnits();
    $("cellsHint").textContent =
      project.cells === "stretch"
        ? "Cells widen to fill the drawer; bins are made to match, so other Gridfinity bins sit loosely."
        : "Standard cells: any Gridfinity bin fits. A flat border fills what's left.";
    $("dims").textContent = `${project.drawer.width} × ${project.drawer.depth} mm`;
    const { x, y } = plan.grid;
    const fmt = (v) => (Math.round(v * 10) / 10).toString();
    $("facts").innerHTML =
      x.count && y.count
        ? [
            ["Cells", `${x.count} × ${y.count}`],
            ["Cell size", `${fmt(x.pitch)} × ${fmt(y.pitch)} mm`],
            ["Border", x.before || y.before ? `${fmt(x.before)} / ${fmt(y.before)} mm` : "none"],
            ["Tiles", `${plan.tileRuns.x.length} × ${plan.tileRuns.y.length}`],
            ["Baseplate", `${BASEPLATE_HEIGHT} mm high`],
          ]
            .map(([k, v]) => `<div><span>${k}</span><b>${v}</b></div>`)
            .join("")
        : "";
  }

  // Bins that no longer fit a smaller grid go.
  function dropStrays() {
    const { x, y } = plan.grid;
    const before = project.bins.length;
    project.bins = project.bins.filter((b) => b.x + b.w <= x.count && b.y + b.d <= y.count);
    if (project.bins.length < before) {
      ui.toast(
        `${before - project.bins.length} bin${before - project.bins.length === 1 ? "" : "s"} no longer fit and went`,
        "info",
      );
      plan = planDrawer(project);
    }
  }

  function update() {
    plan = planDrawer(project);
    dropStrays();
    syncControls();
    drawLayout();
    drawSelected();
    drawParts();
    persist();
  }

  $("fill").addEventListener("click", () => {
    const { x, y } = plan.grid;
    const cells = occupied(null);
    const units = Math.min(project.units, maxUnits());
    let added = 0;
    for (let col = 0; col < x.count; col++)
      for (let row = 0; row < y.count; row++)
        if (!cells.has(`${col},${row}`)) {
          const b = { id: newId(), x: col, y: row, w: 1, d: 1, units, across: 1, along: 1 };
          project.bins.push(b);
          freshBins.add(b.id);
          added++;
        }
    if (!added) ui.toast("Every cell has a bin already", "info");
    update();
  });
  $("clear").addEventListener("click", async () => {
    if (!project.bins.length) return;
    const ok = await ui.confirm({
      title: "Clear the bins?",
      message: `All ${project.bins.length} bins go; the drawer and baseplate stay.`,
      confirmLabel: "Clear",
      destructive: true,
    });
    if (!ok) return;
    project.bins = [];
    selected = null;
    update();
  });

  // ---- saving to Thingport -----------------------------------------------------------------------------------
  /** The drawer from above, as the model's picture. */
  async function layoutPicture() {
    const g = geometryOf();
    const scale = Math.min(1600 / g.W, 1200 / g.D, 4);
    const margin = 40;
    const canvas = document.createElement("canvas");
    canvas.width = Math.round(g.W * scale + 2 * margin);
    canvas.height = Math.round(g.D * scale + 2 * margin);
    const ctx = canvas.getContext("2d");
    const light = theme.mode !== "dark";
    ctx.fillStyle = light ? "#f4f4f2" : "#1d2024";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const box = (x, y, w, h, r) => {
      ctx.beginPath();
      ctx.roundRect(margin + x * scale, margin + y * scale, w * scale, h * scale, r * scale);
    };
    box(0, 0, g.W, g.D, 4);
    ctx.fillStyle = light ? "#e4e4e0" : "#2a2e34";
    ctx.fill();
    ctx.fillStyle = tileColour;
    for (const t of plan.tiles) {
      const rx = plan.tileRuns.x.find((r) => r.start === t.col);
      const ry = plan.tileRuns.y.find((r) => r.start === t.row);
      const outer = cellRect(g, t.col, t.row, t.cols, t.rows);
      box(
        outer.x - rx.before + 0.5,
        outer.y - ry.after + 0.5,
        outer.width + rx.before + rx.after - 1,
        outer.height + ry.before + ry.after - 1,
        2,
      );
      ctx.globalAlpha = 0.35;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    for (const b of plan.bins) {
      if (b.issues.length) continue;
      const r = cellRect(g, b.x, b.y, b.w, b.d);
      box(r.x + 1.5, r.y + 1.5, r.width - 3, r.height - 3, 4);
      ctx.fillStyle = binColour;
      ctx.globalAlpha = 0.85;
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.fillStyle = light ? "#ffffff" : "#0f1114";
      ctx.font = `700 ${Math.round(Math.min(13, r.width / 4) * scale)}px ${theme.fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(
        r.width > 70 ? `${b.w}×${b.d} · ${b.units}u` : `${b.units}u`,
        margin + (r.x + r.width / 2) * scale,
        margin + (r.y + r.height / 2) * scale,
      );
    }
    return new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
  }

  const status = $("status");
  function showStatus(text, actions = []) {
    status.hidden = false;
    status.replaceChildren(document.createTextNode(text));
    for (const [label, run] of actions) {
      const link = document.createElement("button");
      link.type = "button";
      link.className = "gfd-link";
      link.textContent = label;
      link.addEventListener("click", run);
      status.appendChild(link);
    }
  }

  $("save").addEventListener("click", async () => {
    if (!plan.parts.length) return;
    if (plan.problems.some((p) => p.kind === "bin")) {
      const ok = await ui.confirm({
        title: "Save without some bins?",
        message: "The bins marked in red can't be made as they are, and are left out. Save the rest?",
        confirmLabel: "Save",
      });
      if (!ok) return;
    }
    const button = $("save");
    button.disabled = true;
    showStatus("Making the parts…");
    try {
      const title = project.name.trim() || `Drawer ${project.drawer.width} × ${project.drawer.depth}`;
      const files = plan.parts.map((part) => ({
        name: part.file,
        data: stl(meshOf(part), part.name),
        type: "model/stl",
      }));
      showStatus("Saving…");
      const model = await models.create({
        name: title,
        description: description(project, plan),
        tags: ["gridfinity", "drawer organizer"],
        files,
      });
      const picture = await layoutPicture();
      if (picture)
        await models
          .addImages(model.id, [{ name: "layout.png", data: picture, type: "image/png" }])
          .catch(() => undefined);
      lastSaved = model;
      showStatus(`Saved as ${model.name}.`, [
        ["Open it", () => models.open(lastSaved.id)],
        [
          "Add to a collection",
          async () => {
            const collection = await thingport.collections.pick({ title: "Add the drawer to" });
            if (!collection) return;
            await thingport.collections.add(collection.id, [lastSaved.id]);
            ui.toast(`Added to ${collection.name}`, "success");
          },
        ],
      ]);
      ui.toast(`Saved ${model.name}`, "success");
    } catch (err) {
      showStatus("");
      status.hidden = true;
      ui.toast(err.message, "error");
    } finally {
      button.disabled = !plan.parts.length;
    }
  });

  update();

  return () => {
    clearTimeout(persistTimer);
    void storage.set("project", project).catch(() => undefined);
  };
}

function escapeHtml(text) {
  return String(text).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
}
